import{n as e}from"./QTnfLwEv.js";var t=e({default:()=>n}),n={"faq.answer.ecommerce-a1":`<p>Hostinger Ecommerce is an all-in-one ecommerce-first business management platform that puts you in control of your entire online business from a single dashboard.</p><p>Unlike traditional platforms that start with a website, Hostinger Ecommerce starts with your business – you set up your products, payments, and operations first, then choose where and how to sell – your own website, social media, marketplaces, or via a simple shareable link. Hostinger Ecommerce isn't tied to a single storefront, so your business can grow wherever your customers are.</p>`,"faq.answer.ecommerce-a2":`<p>Hostinger Ecommerce is built for sellers at every stage – from your very first sale to managing a multi-channel business.</p><ul><li><b>First-time sellers.</b> Want to sell online without the technical headache or costly add-ons? You'll be up and running in minutes, with no prior experience needed.</li><li><b>Social sellers.</b> If you're currently selling through Instagram DMs, WhatsApp, or TikTok, Hostinger Ecommerce gives you a proper store setup — simple, fast, and without the complexity.</li><li><b>Multi-channel sellers.</b> Already selling in multiple places and tired of juggling separate tools? Hostinger Ecommerce brings your products, inventory, and orders into one dashboard.</li></ul><p>No technical skills required. Name your business, add your first product, set up payments, and choose how you want to sell – whether that's your own website, an existing store, or simply a shareable link. The tools are there to handle the heavy lifting, so you can focus on growing your business.</p>`,"faq.answer.ecommerce-a3":`<p>No – and that's what makes Hostinger Ecommerce different. You can start selling right away by generating a quick product link – a simple, shareable URL that takes customers straight to your product, no website needed. Share it on WhatsApp, Instagram, or any other channel you already use. When you're ready to add a website or connect additional sales channels, that option is always there.</p>`,"faq.answer.ecommerce-a4":`<p>You've got three ways to build your store – pick the one that suits you best, no coding needed.</p><ul><li><b><a href='{websiteBuilderLink}' target='_blank'>Drag-and-drop ecommerce website builder.</a></b> Simply describe your business to AI and get a ready-made website in seconds – then customize it to make it yours by dragging and dropping elements into place.</li><li><b><a href='{horizonsLink}' target='_blank'>Vibe code your online store with AI Builder.</a></b> Chat your store into existence. Describe your vision, refine it in conversation – AI builds everything for you.</li><li><b><a href='{templatesLink}' target='_blank'>Ecommerce website templates.</a></b> Prefer a head start? Choose from a library of ready-made ecommerce templates – pick one that fits your brand and customize it to make it truly yours.</li></ul>`,"faq.answer.ecommerce-a5":`<p>Yes. Think of Hostinger Ecommerce as the kitchen powering your restaurant – it handles your products, inventory, and orders behind the scenes, while your website is just one of the dining rooms customers walk into. Connect your existing website – whether it's built with Hostinger Website Builder, AI Builder, WordPress, or another platform – and everything runs from the same place. You can also add more sales channels alongside your existing site without starting from scratch.</p>`,"faq.answer.ecommerce-a6":`<p>Yes. That's one of the biggest advantages of Hostinger Ecommerce. Whether you're selling on your website, TikTok, Instagram, or a marketplace like Etsy or Amazon, it gives you centralized inventory management for all your shops – meaning your products, inventory, and orders are all managed from a single dashboard. No more switching between tools or worrying about stock going out of sync.</p>`,"faq.answer.ecommerce-a7":`<p>Pretty much anything. Physical products, digital downloads (like eBooks, music, or templates), services that require bookings, print-on-demand merchandise, and subscription-based offerings. Whatever your business model, there's a plan built for it.</p><p>Not sure what to sell yet? We've put together a list of <a href='{link}' target='_blank'>trending product ideas</a> to help you find your niche.</p>`,"faq.answer.ecommerce-a8":`<p>None. You keep 100% of what you earn. Hostinger Ecommerce charges no platform transaction fees, so whether you're processing your first sale or your thousandth, every dollar goes straight to you.</p>`,"faq.answer.ecommerce-a9":`<p>You can accept <a href='{link}' target='_blank'>100+ payment methods</a> globally, including Stripe (Visa, Mastercard, Apple Pay, and Google Pay), PayPal, RazorPay, and Alipay – all with a secure, integrated checkout experience.</p>`,"faq.answer.ecommerce-a10":`<p>For physical products, you can connect Shippo to automate the entire fulfillment process – print labels in seconds, offer real-time tracking, and ship with 40+ carriers including DHL, FedEx, and UPS. For print-on-demand products, Printful handles production and shipping automatically once an order is placed.</p>`,"faq.question.ecommerce-q1":`What is Hostinger Ecommerce?`,"faq.question.ecommerce-q2":`Who is Hostinger Ecommerce solution for?`,"faq.question.ecommerce-q3":`Do I need a website to start selling?`,"faq.question.ecommerce-q4":`How can I create an ecommerce website with Hostinger?`,"faq.question.ecommerce-q5":`Can I use Hostinger Ecommerce if I already have a website?`,"faq.question.ecommerce-q6":`Can I manage multiple sales channels?`,"faq.question.ecommerce-q7":`What can I sell with Hostinger Ecommerce?`,"faq.question.ecommerce-q8":`Are there any transaction fees?`,"faq.question.ecommerce-q9":`What payment methods can my customers use?`,"faq.question.ecommerce-q10":`How does shipping work?`};export{t as n,n as t};